CREATE TABLE "payroll_payments" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "payroll_payments_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"payroll_record_id" bigint NOT NULL,
	"branch_id_snapshot" bigint NOT NULL,
