	"amount" numeric(12, 2) NOT NULL,
	"status" "payroll_payment_status" DEFAULT 'prepared' NOT NULL,
	"employee_bank_account_id" bigint,
	"promptpay_phone_snapshot" varchar(10),
	"bank_code_snapshot" varchar(20),
	"account_holder_name_snapshot" varchar(200),
	"account_number_ciphertext_snapshot" text,
	"account_number_last4_snapshot" varchar(4),
	"prepared_by_user_account_id" bigint NOT NULL,
	"prepared_at" timestamp with time zone DEFAULT now() NOT NULL,
	"paid_by_user_account_id" bigint,
	"paid_at" timestamp with time zone,
	"reference_no" varchar(200),
	"cancelled_by_user_account_id" bigint,
	"cancelled_at" timestamp with time zone,
	"cancellation_reason" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "chk_payment_positive" CHECK ("payroll_payments"."amount" > 0),
	CONSTRAINT "chk_payment_phone" CHECK ("payroll_payments"."promptpay_phone_snapshot" is null or "payroll_payments"."promptpay_phone_snapshot" ~ '^0[689][0-9]{8}$'),
	CONSTRAINT "chk_payment_bank_tuple" CHECK (("payroll_payments"."employee_bank_account_id" is null and "payroll_payments"."bank_code_snapshot" is null and "payroll_payments"."account_holder_name_snapshot" is null and "payroll_payments"."account_number_ciphertext_snapshot" is null and "payroll_payments"."account_number_last4_snapshot" is null) or ("payroll_payments"."employee_bank_account_id" is not null and "payroll_payments"."bank_code_snapshot" is not null and "payroll_payments"."account_holder_name_snapshot" is not null and "payroll_payments"."account_number_ciphertext_snapshot" is not null and "payroll_payments"."account_number_last4_snapshot" is not null and length(trim("payroll_payments"."bank_code_snapshot")) > 0 and length(trim("payroll_payments"."account_holder_name_snapshot")) > 0 and length("payroll_payments"."account_number_ciphertext_snapshot") > 0 and "payroll_payments"."account_number_last4_snapshot" ~ '^[0-9]{4}$')),
	CONSTRAINT "chk_payment_destination" CHECK (("payroll_payments"."payment_method" = 'cash' and "payroll_payments"."employee_bank_account_id" is null and "payroll_payments"."promptpay_phone_snapshot" is null) or ("payroll_payments"."payment_method" = 'transfer' and ("payroll_payments"."promptpay_phone_snapshot" is not null or "payroll_payments"."employee_bank_account_id" is not null))),
	CONSTRAINT "chk_payment_lifecycle" CHECK (("payroll_payments"."status" = 'prepared' and "payroll_payments"."paid_by_user_account_id" is null and "payroll_payments"."paid_at" is null and "payroll_payments"."reference_no" is null and "payroll_payments"."cancelled_by_user_account_id" is null and "payroll_payments"."cancelled_at" is null and "payroll_payments"."cancellation_reason" is null) or ("payroll_payments"."status" = 'paid' and "payroll_payments"."paid_by_user_account_id" is not null and "payroll_payments"."paid_at" is not null and "payroll_payments"."cancelled_by_user_account_id" is null and "payroll_payments"."cancelled_at" is null and "payroll_payments"."cancellation_reason" is null) or ("payroll_payments"."status" = 'cancelled' and "payroll_payments"."cancelled_by_user_account_id" is not null and "payroll_payments"."cancelled_at" is not null and "payroll_payments"."cancellation_reason" is not null and length(trim("payroll_payments"."cancellation_reason")) > 0 and "payroll_payments"."paid_by_user_account_id" is null and "payroll_payments"."paid_at" is null and "payroll_payments"."reference_no" is null))
);
